diff --git a/drivers/net/wireless/mwifiex/ie.c b/drivers/net/wireless/mwifiex/ie.c
index 3bf3d58bbc02..2a6cd0df25d5 100644
--- a/drivers/net/wireless/mwifiex/ie.c
+++ b/drivers/net/wireless/mwifiex/ie.c
@@ -324,10 +324,11 @@ done:
 int mwifiex_set_mgmt_ies(struct mwifiex_private *priv,
 			 struct cfg80211_beacon_data *info)
 {
-	struct mwifiex_ie *gen_ie;
+	struct mwifiex_ie *gen_ie = NULL;
 	struct ieee_types_header *rsn_ie, *wpa_ie = NULL;
 	u16 rsn_idx = MWIFIEX_AUTO_IDX_MASK, ie_len = 0;
 	const u8 *vendor_ie;
+	int err = 0;

 	if (info->tail && info->tail_len) {
 		gen_ie = kzalloc(sizeof(struct mwifiex_ie), GFP_KERNEL);
@@ -341,6 +342,10 @@ int mwifiex_set_mgmt_ies(struct mwifiex_private *priv,
 		rsn_ie = (void *)cfg80211_find_ie(WLAN_EID_RSN,
 						  info->tail, info->tail_len);
 		if (rsn_ie) {
+			if (rsn_ie->len + 2 > IEEE_MAX_IE_SIZE) {
+				err = -EINVAL;
+				goto out;
+			}
 			memcpy(gen_ie->ie_buffer, rsn_ie, rsn_ie->len + 2);
 			ie_len = rsn_ie->len + 2;
 			gen_ie->ie_length = cpu_to_le16(ie_len);
@@ -352,6 +357,10 @@ int mwifiex_set_mgmt_ies(struct mwifiex_private *priv,
 						    info->tail_len);
 		if (vendor_ie) {
 			wpa_ie = (struct ieee_types_header *)vendor_ie;
+			if (ie_len + wpa_ie->len + 2 > IEEE_MAX_IE_SIZE) {
+				err = -EINVAL;
+				goto out;
+			}
 			memcpy(gen_ie->ie_buffer + ie_len,
 			       wpa_ie, wpa_ie->len + 2);
 			ie_len += wpa_ie->len + 2;
@@ -362,8 +371,8 @@ int mwifiex_set_mgmt_ies(struct mwifiex_private *priv,
 			if (mwifiex_update_uap_custom_ie(priv, gen_ie, &rsn_idx,
 							 NULL, NULL,
 							 NULL, NULL)) {
-				kfree(gen_ie);
-				return -1;
+				err = -EINVAL;
+				goto out;
 			}
 			priv->rsn_idx = rsn_idx;
 		}
@@ -372,6 +381,10 @@ int mwifiex_set_mgmt_ies(struct mwifiex_private *priv,
 	}

 	return mwifiex_set_mgmt_beacon_data_ies(priv, info);
+
+out:
+	kfree(gen_ie);
+	return err;
 }

 /* This function removes management IE set */
